od(xi.mod.CHR, 7)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bunch_of_gysahl_greens.lua"]={["Path"]="scripts/items/bunch_of_gysahl_greens.lua",["SHA256"]="efbf2be487878f0e42359366febe7ad880e2017105f768cf726b155ebfa5a3e4",["Text"]="-----------------------------------\n-- ID: 4545\n-- Item: Bunch of Gysahl Greens\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility +3\n-- Vitality -5\n-- Additional Effect with Chocobo Shirt\n-- Agility +10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local chocoboShirt = target:getMod(xi.mod.APPRECIATE_GYSAHL_GREENS)\n    target:addStatusEffect(xi.effect.FOOD, { power = chocoboShirt, duration = 300, origin = user, subType = 4545 })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    local power = effect:getPower()\n    if power == 0 then\n        effect:addMod(xi.mod.AGI, 3)\n        effect:addMod(xi.mod.VIT, -5)\n    else\n        effect:addMod(xi.mod.AGI, 13)\n        effect:addMod(xi.mod.VIT, -5)\n    end\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bunch_of_pamamas.lua"]={["Path"]="scripts/items/bunch_of_pamamas.lua",["SHA256"]="5aef4f3dba5d49c1da0163ac88aa5e8fba0624f329eca5be4d2094f7da4f85fb",["Text"]="-----------------------------------\n-- ID: 4468\n-- Item: Bunch of Pamamas\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Strength -3\n-- Intelligence 1\n-- Additional Effect with Opo-Opo Crown\n-- HP 50\n-- MP 50\n-- CHR 14\n-- Additional Effect with Kinkobo or\n-- Primate Staff\n-- DELAY -90\n-- ACC 10\n-- Additional Effect with Primate Staff +1\n-- DELAY -80\n-- ACC 12\n-----------------------------------\n---