xi.mod.FOOD_DEFP, 25)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 75)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/butterpear.lua"]={["Path"]="scripts/items/butterpear.lua",["SHA256"]="6232242140fa371d9564ad3dfe9265004c2026dfd57c1c3c91c6b3701e355da7",["Text"]="-----------------------------------\n-- ID: 5908\n-- Item: Butterpear\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility +4\n-- Vitality +1\n-- Resist Amnesia +20\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 4)\n    effect:addMod(xi.mod.VIT, 1)\n    effect:addMod(xi.mod.AMNESIARES, 20)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/byakkos_axe.lua"]={["Path"]="scripts/items/byakkos_axe.lua",["SHA256"]="d6b6e13615868a7cc8d7da40d3202cfc3209925dc9e31ff03ee503de9685fc6a",["Text"]="-----------------------------------\n-- ID: 18198\n-- Item: Byakko's Axe\n-- Additional effect: wind damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 2, -- TODO: this has negative scaling, as in if you have low dINT it procs more. This is capped dINT.\n        basePower      = math.randomInt(22, 30),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WIND,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/ca_cuong.lua"]={["Path"]="scripts/items/ca_cuong.lua",["SHA256"]="322126de09feb9eeaad7c52d50a2b4d1f26f008cb09b2543bbedb3dd23b6e149",["Text"]="-----------------------------------\n-- ID: 5474\n-- Item: Ca Cuong\n-- Food Effect: 5 Min, Mithra only\n-----------------------------------\n-- Dexterity +2\n-- Mind -4\n-- Agility +2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\n    effect:addMod(xi.mod.AGI, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/caedarva_frog.lua"]={["Path"]="scripts/items/caedarva_frog.lua",["SHA256"]="aae698f7d0fd9e8e509634a38b748d4d868e1ab166aeb0a41996c231c8b56a29",["Text"]="-----------------------------------\n-- ID: 5465\n-- Item: Caedarva Frog\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Agility 2\n-- Mind -4\n-- Evasion 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.EVA, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cage_of_a._remnants_fireflies.lua"]={["Path"]="scripts/items/cage_of_a._remnants_fireflies.lua",["SHA256"]="0c1e39a3bcb82dd097d2dcedaddbd17346f0797520222c3d8486e0323c0f01a9",["Text"]="-----------------------------------\n-- ID: 5399\n-- A. Rem. Fireflies\n-- Transports the user out of Arrapago Remnants\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getZoneID() == xi.zone.ARRAPAGO_REMNANTS then\n        return 0\n    end\n\n    return xi.msg.basic.ITEM_UNABLE_TO_USE_2\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.A_REM, duration = 1, origin = user, icon = 0 })\nend\n\nitemObject.onItemDrop = function(target, item)\n    target:addTempItem(xi.item.CAGE_OF_A_REMNANTS_FIREFLIES)\nend\n\nreturn itemObject\n"},["scripts/items/cage_of_azouph_fireflies.lua"]={["Path"]="scripts/items/cage_of_azouph_fireflies.lua",["SHA256"]="08a635530513e4b4e947f2334e23864f1ecf0ffbf14835cbdd0e597a3b0fbb33",["Text"]="-----------------------------------\n-- ID: 5343\n-- Azouph Fireflies\n-- Transports the user to Azouph Isle\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getZoneID() == xi.zone.LEUJAOAM_SANCTUM then\n        return 0\n    end\n\n    return xi.msg.basic.ITEM_UNABLE_TO_USE_2\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.AZOUPH, duration = 1, origin = user, icon = 0 })\nend\n\nitemObject.onItemDrop = function(target, item)\n    target:addTempItem(xi.item.CAGE_OF_AZOUPH_FIREFLIES)\nend\n\nreturn itemObject\n"},["scripts/items/cage_of_b._remnants_fireflies.lua"]={["Path"]="scripts/items/cage_of_b._remnants_fireflies.lua",["SHA256"]="4eabfb9fc23466c29ea5484b7be6f67863a44110a066e3af6063515fb078bf06",["Text"]="-----------------------------------\n-- ID: 5400\n-- B. Rem. Fireflies\n-- Transports the user out of Bhaflau Remnants\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getZoneID() == xi.zone.BHAFLAU_REMNANTS then\n        return 0\n    end\n\n    return xi.msg.basic.ITEM_UNABLE_TO_USE_2\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.B_REM, duration = 1, origin = user, icon = 0 })\nend\n\nitemObject.onItemDrop = function(target, item)\n    target:addTempItem(xi.item.CAGE_OF_B_REMNANTS_FIREFLIES)\nend\n\nreturn itemObject\n"},["scripts/items/cage_of_bhaflau_fireflies.lua"]={["Path"]="scripts/items/cage_of_bhaflau_fireflies.lua",["SHA256"]="d537a679995609613df2992374f9ce5320d9284a583847b72eea6500fa0bcdae",["Text"]="-----------------------------------\n-- ID: 5344\n-- Bhaflau Fireflies\n-- Transports the user to Mamool Ja Staging Point\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getZoneID() == xi.zone.MAMOOL_JA_TRAINING_GROUNDS then\n        return 0\n    end\n\n    return xi.msg.basic.ITEM_UNABLE_TO_USE_2\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.BHAFLAU, duration = 1, origin = user, icon = 0 })\nend\n\nitemObject.onItemDrop = function(target, item)\n    target:addTempItem(xi.item.CAGE_OF_BHAFLAU_FIREFLIES)\nend\n\nreturn itemObject\n"},["scripts/items/cage_of_cutter_fireflies.lua"]={["Path"]="scripts/items/cage_of_cutter_fireflies.lua",["SHA256"]="3d98de0c5dc00c9dcc0d154ef6172807318e811704fd4c5d66