_UNABLE_TO_USE_2\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.ALZADAAL, duration = 1, origin = user, icon = 0 })\nend\n\nitemObject.onItemDrop = function(target, item)\n    target:addTempItem(xi.item.UNDERSEA_RUINS_FIREFLIES)\nend\n\nreturn itemObject\n"},["scripts/items/cage_of_z._remnants_fireflies.lua"]={["Path"]="scripts/items/cage_of_z._remnants_fireflies.lua",["SHA256"]="6fa19417f68e309f8e7ca17bc3d828444b07e84acbf95e681092dc4d0ab35db5",["Text"]="-----------------------------------\n-- ID: 5398\n-- Z. Rem. Fireflies\n-- Transports the user out of Zhayolm Remnants\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getZoneID() == xi.zone.ZHAYOLM_REMNANTS then\n        return 0\n    end\n\n    return xi.msg.basic.ITEM_UNABLE_TO_USE_2\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.Z_REM, duration = 1, origin = user, icon = 0 })\nend\n\nitemObject.onItemDrop = function(target, item)\n    target:addTempItem(xi.item.CAGE_OF_Z_REMNANTS_FIREFLIES)\nend\n\nreturn itemObject\n"},["scripts/items/cage_of_zhayolm_fireflies.lua"]={["Path"]="scripts/items/cage_of_zhayolm_fireflies.lua",["SHA256"]="1ad6bf902a34c643fa1ec25b3ed23f4146f0891bdeac39578989064b7817d7bf",["Text"]="-----------------------------------\n-- ID: 5345\n-- Item: Zhayolm Fireflies\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getZoneID() == xi.zone.LEBROS_CAVERN then\n        return 0\n    end\n\n    return xi.msg.basic.ITEM_UNABLE_TO_USE_2\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.ZHAYOLM, duration = 1, origin = user, icon = 0 })\nend\n\nitemObject.onItemDrop = function(target, item)\n    target:addTempItem(xi.item.CAGE_OF_ZHAYOLM_FIREFLIES)\nend\n\nreturn itemObject\n"},["scripts/items/caliber_ring.lua"]={["Path"]="scripts/items/caliber_ring.lua",["SHA256"]="4da48904b1e881620e37ed1dd99c4a899ecbafae9a0f7f1c184b2deb6d502913",["Text"]="-----------------------------------\n-- ID: 26164\n-- Item: caliber ring\n-- Experience point bonus\n-----------------------------------\n-- Bonus: +150%\n-- Duration: 720 min\n-- Max bonus: 30000 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.DEDICATION) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.DEDICATION\n    local power     = 150\n    local duration  = 43200\n    local subpower  = 30000\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/calico_comet.lua"]={["Path"]="scripts/items/calico_comet.lua",["SHA256"]="5053a96a6e03ca7f7a1c4fd2ec1f2d781d8f44eb31af800529e213a195af90c8",["Text"]="-----------------------------------\n-- ID: 5715\n-- Item: Calico Comet\n-- Food Effect: 5 Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/candy_cane.lua"]={["Path"]="scripts/items/candy_cane.lua",["SHA256"]="7bb37dbb314bbd8ba4a0be2c73c11ea506439d3d933561b178936da4ee180dfd",["Text"]="-----------------------------------\n-- ID: 5622\n-- Item: Candy Cane\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- Intelligence 4\n-- Mind 4\n-- MP Recovery while healing 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.INT, 4)\n    effect:addMod(xi.mod.MND, 4)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/candy_ring.lua"]={["Path"]="scripts/items/candy_ring.lua",["SHA256"]="0be98bea19501ae29470990fba9847b6313768c5a63ab2b5b8996589c9c12900",["Text"]="-----------------------------------\n-- ID: 5621\n-- Item: Candy Ring\n-- Food Effect: 4 Hrs, All Races\n-----------------------------------\n-- Dexterity 4\n-- Agility 4\n-- Charisma 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.AGI, 4)\n    effect:addMod(xi.mod.CHR, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/capacity_ring.lua"]={["Path"]="scripts/items/capacity_ring.lua",["SHA256"]="e385ae58f524b0bc2fac8cc002e4875615a74564fc1f8651ddd03bdcd58e7ef9",["Text"]="-----------------------------------\n-- ID: 28546\n-- Item: capacity ring\n-- Capacity point bonus\n-----------------------------------\n-- Bonus: +50%\n-- Duration: 720 min\n-- Max bonus: 30000 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.COMMITMENT) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.COMMITMENT\n    local power     = 50\n    local duration  = 43200\n    local subpower  = 30000\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/carbuncles_pole.lua"]={["Path"]="scripts/items/carbuncles_pole.lua",["SHA256"]="a70e50dc04f44a076d4e4b1e6116a9f3adc67ecdc4ead0df6206fc19916eb453",["Text"]="-----------------------------------\n-- ID: 18581\n-- Item: Carbuncles Pole\n-- Item Effect: Restores 160-170 HP\n-----------------------------------\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local hpCap  = target:getMaxHP() - target:getHP()\n    local hpHeal = utils.clamp(math.randomInt(160, 170), 0, hpCap)\n    target:addHP(hpHeal)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, hpHeal)\nend\n\nreturn itemObject\n"},["scripts/items/carnage_blade.lua"]={["Path"]="scripts/items/carnage_blade.lua",["SHA256"]="4cf1a8818fadb53fd9be4d593b85f0f1f18038985c84e70fd35856d4a2da186a",["Text"]="-----------------------------------\n-- ID: 16827\n-- Item: Carnage Blade\n-- Additional effect: en-drain\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n\n    local pTable =\n    {\n        chance          = xi.additionalEffect.linearProcRate(dStat, 32, 8, 12),\n        basePower       = 8 + utils.clamp(dStat, -3, 16) + utils.clamp(math.floor((dStat - 16) / 2), 0, 16),\n        attackType      = xi.attackType.PHYSICAL,\n        physicalElement = xi.damageType.SLASHING,\n        magicalElement  = xi.element.DARK,\n        canResist       = true,\n        lowestResist    = 0.5,\n        limitUndead     = true,\n        drainHP         = true,\n        overDrain       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/carnage_lance.lua"]={["Path"]="scripts/items/carnage_lance.lua",["SHA256"]="d91f0924f497986e0de5e64779e0479fd54013da7c0a19eaaf71b330a3b687bc",["Text"]="-----------------------------------\n-- ID: 16881\n-- Item: Carnage Lance\n-- Additional effect: en-drain\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n\n    local pTable =\n    {\n        chance          = xi.additionalEffect.linearProcRate(dStat, 32, 7, 9), -- TODO: get more samples\n        basePower       = 8 + utils.clamp(dStat, -3, 16) + utils.clamp(math.floor((dStat - 16) / 2), 0, 16),\n        attackType      = xi.attackType.PHYSICAL,\n        physicalElement = xi.damageType.PIERCING,\n        magicalElement  = xi.element.DARK,\n        canResist       = true,\n        lowestResist    = 0.5,\n        limitUndead     = true,\n        drainHP         = true,\n        overDrain       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/carnage_rapier.lua"]={["Path"]="scripts/items/carnage_rapier.lua",["SHA256"]="c673393638c0d21b016cc8d84f33ba7e664f0d62b84b5ae17edea05e97c75b3c",["Text"]="-----------------------------------\n-- ID: 16824\n-- Item: Carnage Rapier\n-- Additional effect: en-drain\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n\n    local pTable =\n    {\n        chance          = xi.additionalEffect.linearProcRate(dStat, 32, 8, 12), -- Needs better data, but looks like Bloody Blade's proc rate\n        basePower       = 8 + utils.clamp(dStat, -3, 16) + utils.clamp(math.floor((dStat - 16) / 2), 0, 16),\n        attackType      = xi.attackType.PHYSICAL,\n        physicalElement = xi.damageType.PIERCING,\n        magicalElement  = xi.element.DARK,\n        canResist       = true,\n        lowestResist    = 0.5,\n        limitUndead     = true,\n        drainHP         = true,\n        overDrain       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/carnage_sword.lua"]={["Path"]="scripts/items/carnage_sword.lua",["SHA256"]="6d9efc8e0715775ea80f7435570d8da796143b6e5661682cedf7c0dcf97318b2",["Text"]="-----------------------------------\n-- ID: 17646\n-- Item: Carnage Sword\n-- Additional effect: en-drain\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n\n    local pTable =\n    {\n        chance          = xi.additionalEffect.linearProcRate(dStat, 32, 8, 12),\n        basePower       = 8 + utils.clamp(dStat, -3, 16) + utils.clamp(math.floor((dStat - 16) / 2), 0, 16),\n        attackType      = xi.attackType.PHYSICAL,\n        physicalElement = xi.damageType.SLASHING,\n        magicalElement  = xi.element.DARK,\n        canResist       = true,\n        lowestResist    = 0.5,\n        limitUndead     = true,\n        drainHP         = true,\n        overDrain       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/carp_sushi.lua"]={["Path"]="scripts/items/carp_sushi.lua",["SHA256"]="237e6a2ed8d529efecbb8d4a2bc218a07c9c4cb74fad0a3987a5278eea52f38b",["Text"]="-----------------------------------\n-- ID: 4407\n-- Item: carp_sushi\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Dexterity 1\n-- Accuracy % 10 (cap 52)\n-- HP Recovered While Healing 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.FOOD_ACCP, 10)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 52)\n    effect:addMod(xi.mod.HPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/carpenters_belt.lua"]={["Path"]="scripts/items/carpenters_belt.lua",["SHA256"]="8a4b4b4e330250862a5aa93d437bb5403604d25ccb7e1c30242e27b315844304",["Text"]="-----------------------------------\n-- ID: 15444\n-- Item: Carpenter's belt\n-- Enchantment: Synthesis image support\n-- Duration: 8Min\n-- Woodworking Skill +3\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.WOODWORKING_IMAGERY) then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.WOODWORKING_IMAGERY, { power = 3, duration = 480, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/casaba_melon_tank.lua"]={["Path"]="scripts/items/casaba_melon_tank.lua",["SHA256"]="bd68874a97c8b682c8dd91a05b4fceeeca3e5db92cf7e55f1e8a5b8a9c0eb8ca",["Text"]="-----------------------------------\n--  ID: 13682\n--  Casaba Melon Tank\n--  When used, you will obtain a Melon Juice\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BOTTLE_OF_MELON_JUICE, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/castellanus_cell.lua"]={["Path"]="scripts/items/castellanus_cell.lua",["SHA256"]="945a0f4f8b4cc4199845519808e33df27f09da61a6d707d97cd6b3b00e239a48",["Text"]="-----------------------------------\n-- Castellanus Cell\n-- ID 5366\n-- Unlocks head and neck equipment\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.salvage.onCellItemCheck(target, xi.effect.ENCUMBRANCE_I, 0x0210)\nend\n\nitemObject.onItemUse = function(target)\n    return xi.salvage.onCellItemUse(target, xi.effect.ENCUMBRANCE_I, 0x0210, 1)\nend\n\nreturn itemObject\n"},["scripts/items/casters_die.lua"]={["Path"]="scripts/items/casters_die.lua",["SHA256"]="6666671000ff74ebe2a3252a9b54f95ea40558e9dd7a25b2051590bc76151364",["Text"]="-----------------------------------\n-- ID: 5498\n-- Casters Die\n-- Teaches the job ability Casters Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.CASTERS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.CASTERS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/cathedral_salad.lua"]={["Path"]="scripts/items/cathedral_salad.lua",["SHA256"]="1b7eef096a4034d4d2f6015ed7b9897bffd9ed82fc5cbab9e8ed097022ad10cd",["Text"]="-----------------------------------\n-- ID: 5679\n-- Item: cathedral_salad\n-- Food Effect: 4 Hrs, All Races\n-----------------------------------\n-- MP 15% Cap 90\n-- Agility 7\n-- Mind 7\n-- Strength -5\n-- Vitality -5\n-- Ranged Accuracy +17\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 15)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 90)\n    effect:addMod(xi.mod.AGI, 7)\n    effect:addMod(xi.mod.MND, 7)\n    effect:addMod(xi.mod.STR, -5)\n    effect:addMod(xi.mod.VIT, -5)\n    effect:addMod(xi.mod.RACC, 17)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cavernous_score.lua"]={["Path"]="scripts/items/cavernous_score.lua",["SHA256"]="b43bf61b5823969650f2eeb08f1037fb13161fa183467e7ee935be0bde50566f",["Text"]="-----------------------------------\n-- ID: 6173\n-- Item: Cavernous Score\n-- A musical score composed by Lewenhart.\n-- Its notes symbolize the damp and musty air that stagnates within an underground cave.\n-- Adventurers note that reading it increases one's string instrument skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.STRING_INSTRUMENT)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.STRING_INSTRUMENT)\nend\n\nreturn itemObject\n"},["scripts/items/ccb_polymer_pump.lua"]={["Path"]="scripts/items/ccb_polymer_pump.lua",["SHA256"]="953a0cbc2123faf43ad8fd51c68059b5dc2acc6b69c074d5ace9467b2caef088",["Text"]="-----------------------------------\n-- ID: 5268\n-- Item: CCB Polymer Pump\n-- Used during CoP 6-4 One To Be Feared on Ultima or Omega to inflict a 1 minute amnesia\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result      = xi.msg.basic.ITEM_UNABLE_TO_USE\n    local battlefield = caster:getBattlefieldID()\n\n    if\n        battlefield == xi.battlefield.id.ONE_TO_BE_FEARED and\n        (target:getName() == 'Omega' or target:getName() == 'Ultima') and\n        not target:hasStatusEffect(xi.effect.AMNESIA)\n    then\n        result = 0\n    elseif target:checkDistance(caster) > 10 then\n        result = xi.msg.basic.TOO_FAR_AWAY\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.AMNESIA, { power = 1, duration = 60, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/cehuetzi_snow_cone.lua"]={["Path"]="scripts/items/cehuetzi_snow_cone.lua",["SHA256"]="6a663b3499d5cdc8d605235aba377d296e805c110810c905e3890e1f44a7271f",["Text"]="-----------------------------------\n-- ID: 6223\n-- Item: Cehuetzi snow cone\n-- Food Effect: 30 Min, All Races\n-----------------------------------\n-- MP +20% (cap 100)\n-- INT +5\n-- MND +5\n-- Magic Atk. Bonus +13\n-- Lizard Killer +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 20)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 100)\n    effect:addMod(xi.mod.INT, 5)\n    effect:addMod(xi.mod.MND, 5)\n    effect:addMod(xi.mod.MATT, 13)\n    effect:addMod(xi.mod.LIZARD_KILLER, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/chaosbringer.lua"]={["Path"]="scripts/items/chaosbringer.lua",["SHA256"]="7cc03e01fdf1b12fee17f7f42ef4404279559bd0e9f9e31c1c4823a8e196f209",["Text"]="-----------------------------------\n-- ID: 16607\n-- Chaosbringer\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemDrop = function(target, item, recycleBin)\n    if not recycleBin then\n        target:setCharVar('ChaosbringerKills', 0)\n    end\nend\n\nitemObject.onItemEquip = function(target, item)\n    target:addListener('ATTACK', 'CHAOSBRINGER_ATTACK', function(attacker, attackTarget, action)\n        if\n            attackTarget:getHP() == 0 and\n            (attacker:getQuestStatus(xi.questLog.BASTOK, xi.quest.id.bastok.BLADE_OF_DARKNESS) == xi.questStatus.QUEST_ACCEPTED or\n            attacker:getQuestStatus(xi.questLog.BASTOK, xi.quest.id.bastok.BLADE_OF_DEATH) == xi.questStatus.QUEST_ACCEPTED) and\n            attacker:getCharVar('ChaosbringerKills') < 200\n        then\n            attacker:incrementCharVar('ChaosbringerKills', 1)\n        end\n    end)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:removeListener('CHAOSBRINGER_ATTACK')\nend\n\nreturn itemObject\n"},["scripts/items/chapuli_quiver.lua"]={["Path"]="scripts/items/chapuli_quiver.lua",["SHA256"]="bb070c9e25ea8d82a0cee13db4ebd86e6a04feea48d8a3ca6c64a5371efc6ba9",["Text"]="-----------------------------------\n-- ID: 6137\n-- Chapuli Quiver\n-- When used, you will obtain one stack of Chapuli Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.CHAPULI_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/chariot_band.lua"]={["Path"]="scripts/items/chariot_band.lua",["SHA256"]="ef0ff626a2ba21fa6152247f07d3fbf34116f13238e80c9d21b749eddafd83c9",["Text"]="-----------------------------------\n-- ID: 15761\n-- Item: chariot band\n-- Experience point bonus\n-----------------------------------\n-- Bonus: +75%\n-- Duration: 720 min\n-- Max bonus: 10000 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.DEDICATION) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.DEDICATION\n    local power     = 75\n    local duration  = 43200\n    local subpower  = 10000\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/charisma_potion.lua"]={["Path"]="scripts/items/charisma_potion.lua",["SHA256"]="6aef86c10071735d9297b6e1381c9e24ea65ec7df433092a8355387b7a0be2b6",["Text"]="-----------------------------------\n--  ID: 4211\n--  Item: Charisma Potion\n--  Charisma 7\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.CHR_BOOST, { power = 7, duration = 180, origin = user })\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 900, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/charred_salisbury_steak.lua"]={["Path"]="scripts/items/charred_salisbury_steak.lua",["SHA256"]="3990f217dc1b3adb65503cea9b857b5a1019a7f647349edcebafd6b283faf137",["Text"]="-----------------------------------\n-- ID: 5925\n-- Item: Charred Salisbury Steak\n-- Food Effect: 240 Min, All Races\n-----------------------------------\n-- HP +32\n-- Strength +8\n-- Intelligence -6\n-- Attack % 22 Cap 165\n-- Ranged Attack %22 Cap 165\n-- Dragon Killer +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 32)\n    effect:addMod(xi.mod.STR, 8)\n    effect:addMod(xi.mod.INT, -6)\n    effect:addMod(xi.mod.FOOD_ATTP, 22)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 165)\n    effect:addMod(xi.mod.FOOD_RATTP, 22)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 165)\n    effect:addMod(xi.mod.DRAGON_KILLER, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cheese_sandwich.lua"]={["Path"]="scripts/items/cheese_sandwich.lua",["SHA256"]="87dd19b3048c7ec581201d8f79d3b444fa8e63a5a88dfb7dae829aced7e407a9",["Text"]="-----------------------------------\n-- ID: 5686\n-- Item: cheese_sandwich\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- HP 10\n-- Agility 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.AGI, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cheese_sandwich_+1.lua"]={["Path"]="scripts/items/cheese_sandwich_+1.lua",["SHA256"]="630dfda84738e25d5890de8a3463e5bed23c796a5367e4ccb345bafb77520daf",["Text"]="-----------------------------------\n-- ID: 5687\n-- Item: cheese_sandwich_+1\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- HP 10\n-- Agility 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.AGI, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cherry_macaron.lua"]={["Path"]="scripts/items/cherry_macaron.lua",["SHA256"]="1da5cc6a1471dc8c9a72092d76580a39a7287f74a8b820e1b7818cb8f0ac750a",["Text"]="-----------------------------------\n-- ID: 5779\n-- Item: cherry_macaron\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Increases rate of synthesis success +3%\n-- Increases synthesis skill gain rate +3%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.SYNTH_SUCCESS_RATE, 3)\n    effect:addMod(xi.mod.SYNTH_SKILL_GAIN, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cherry_muffin.lua"]={["Path"]="scripts/items/cherry_muffin.lua",["SHA256"]="674b88bcf4545c0e2a6fefafdae250f24dc3b607697b5611a09e89a828fd304f",["Text"]="-----------------------------------\n-- ID: 5653\n-- Item: Cherry Muffin\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Intelligence 1\n-- Magic % 10\n-- Magic Cap 80\n-- Agility -1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.INT, 1)\n    effect:addMod(xi.mod.FOOD_MPP, 10)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 80)\n    effect:addMod(xi.mod.AGI, -1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cherry_muffin_+1.lua"]={["Path"]="scripts/items/cherry_muffin_+1.lua",["SHA256"]="c8a6959ba2e5f25567da192cf37849b0a0c50c7c24d4891c7a3497284e2a065c",["Text"]="-----------------------------------\n-- ID: 5654\n-- Item: Cherry Muffin\n-- Food Effect: 1Hr, All Races\n-----------------------------------\n-- Intelligence 2\n-- MP % 10 (cap 85)\n-- Agility -1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.INT, 2)\n    effect:addMod(xi.mod.FOOD_MPP, 10)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 85)\n    effect:addMod(xi.mod.AGI, -1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cheval_salmon.lua"]={["Path"]="scripts/items/cheval_salmon.lua",["SHA256"]="87c5f82ffa741fbe98c8a29be2100fe9d3ab7d28a29fa0dc4ecd80f1d8ddd2e3",["Text"]="-----------------------------------\n-- ID: 4379\n-- Item: cheval_salmon\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Charisma -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.CHR, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/chicken_knife.lua"]={["Path"]="scripts/items/chicken_knife.lua",["SHA256"]="e444fb33122ec70bb0ee06738eba3daf96ec545e51176d77b8d62e06ebdf251c",["Text"]="-----------------------------------\n-- ID: 17615\n-- Chicken Knife\n-----------------------------------\nlocal itemObject = {}\n\nitemObject.onItemEquip = function(player, item)\n    player:addListener('ATTACK', 'CHICKEN_KNIFE_ATTACK', function(playerArg, mob)\n        local dLvl = mob:getMainLvl() - playerArg:getMainLvl()\n        if dLvl >= 1 then\n            -- exponential approx to data points from retail capture\n            local chance = utils.clamp(100 * 0.0096906 * math.exp(0.176839 * dLvl), 1.33, 33)\n            if math.randomInt(1, 100) <= chance then\n                local effect = player:getStatusEffect(xi.effect.FLEE)\n                if effect then\n                    effect:setTick(0)\n                    effect:resetStartTime()\n                    effect:setIcon(xi.effect.FLEE)\n                else\n                    player:addStatusEffect(xi.effect.FLEE, { power = 10000, duration = 30, origin = player })\n                end\n            end\n        end\n    end)\nend\n\nitemObject.onItemUnequip = function(player, item)\n    player:removeListener('CHICKEN_KNIFE_ATTACK')\nend\n\nreturn itemObject\n"}};
